from collections import defaultdict, OrderedDict

class _Node:
    __slots__ = ("key", "value", "freq")
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.freq = 1

class LFUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.min_freq = 0
        self.by_key: dict[int, _Node] = {}
        # freq -> OrderedDict[key, node], insertion order = recency within freq
        self.by_freq: dict[int, OrderedDict] = defaultdict(OrderedDict)

    def _touch(self, node: _Node):
        f = node.freq
        del self.by_freq[f][node.key]
        if not self.by_freq[f] and f == self.min_freq:
            self.min_freq += 1
        node.freq = f + 1
        self.by_freq[f + 1][node.key] = node  # tail = most recent

    def get(self, key: int) -> int:
        node = self.by_key.get(key)
        if node is None:
            return -1
        self._touch(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.cap == 0:
            return
        if key in self.by_key:
            node = self.by_key[key]
            node.value = value
            self._touch(node)
            return
        if len(self.by_key) >= self.cap:
            # evict LRU within lowest frequency
            evict_key, _ = self.by_freq[self.min_freq].popitem(last=False)
            del self.by_key[evict_key]
        node = _Node(key, value)
        self.by_key[key] = node
        self.by_freq[1][key] = node
        self.min_freq = 1
